(* [comment removed for export] *)
Lemma regs_ok_pin : forall E sr regs (r : reg) e,
  regs_ok E sr regs ->
  getr regs r = edenot E e ->
  regs_ok E (sr_upd sr (ridx r) e) regs.
Proof.
