Lemma sc_disjoint_of_regions : forall segs base E a1 n1 a2 n2 r1 r2,
  rg_wf r1 -> rg_wf r2 -> rg_disj r1 r2 ->
  covers r1 (adenot E a1) n1 -> covers r2 (adenot E a2) n2 ->
  sc_denot segs base E (SCDisjoint a1 n1 a2 n2).
Proof.
