Lemma chain_mst_realizes : forall segs scfg ms ms' model T,
  m_halted model = None ->
  m_vm_lazy model = [] ->
  msteps segs ms ms' ->
  ShapeAlg.realizes segs scfg (mkCfg ms' model) T ->
  ShapeAlg.realizes segs scfg (mkCfg ms model) T.
Proof.
  intros segs scfg ms ms' model T Hh Hlazy Hms Hr.
  chain_mst; [exact Hms | exact Hr].
Qed.

